func loadPrimaryMetadataRootTree(ctx context.Context, repo *git.Repository, refs checkpoint.PersistentRefs) (*object.Tree, error) {
	if tree, err := strategy.GetMetadataRefTree(repo, refs.Primary); err == nil {
